                    lvl.nodes[lvlPos.nextNodesFreeSlot] = lvl.nodes[i];
                    lvl.positions[lvlPos.nextNodesFreeSlot] = lvl.positions[i] >> 1;
                }
                ++lvlPos.nextNodesFreeSlot;
            }
        }

