        lvlPos.edgePos >>= 1;

        // parents were written in place into the low slots; that prefix is the next level.
        lvlPos.currentNodesFreeSlot = lvlPos.nextNodesFreeSlot;
        lvlPos.nextNodesFreeSlot = 0;
        return (lvl, lvlPos);
