            self.depth,
            self.size,
            leaf,
            leafIndex,
            proofSiblings,
            hasher
        );
        uint256 currentRoot = InternalSkinnyIMTEvent._root(self);
        return provenRoot == currentRoot;
    }

    function verifyMany(
        SkinnyIMTDataEvent storage self,
        uint256[] calldata leaves,
        uint256[] calldata leafIndexes,
        uint256[] calldata proofSiblings
