        uint256 provenRoot = InternalSkinnyIMTEvent._proofManyToRootBN254(
            self.depth,
            self.size,
            leaves,
            leafIndexes,
            proofSiblings,
            hasher
        );
        uint256 currentRoot = InternalSkinnyIMTEvent._root(self);
        return provenRoot == currentRoot;
    }
}

